#include "dfre/events.hpp"
#include "dfre/mission_sound_runtime.hpp"
#include <fstream>
#include <iostream>
#include <map>
using namespace dfre;
using U=std::uint32_t;
namespace {
void check(bool ok,const char* text){if(!ok)throw std::runtime_error(text);}
template<class F>void fails(F f){bool stopped=false;try{f();}catch(const std::exception&){stopped=true;}check(stopped,"Missing required source failure");}
struct Bytes{std::map<U,unsigned char> data;void add(U a,U n){for(U i=0;i<n;++i)data[a+i]=0;}U get(U a,unsigned w){U v=0;for(U i=0;i<w;++i)v|=U(data.at(a+i))<<(i*8);return v;}void put(U a,unsigned w,U v){for(U i=0;i<w;++i)data.at(a+i)=static_cast<unsigned char>(v>>(i*8));}};
struct Host:EventHost{MissionEventMemory* memory{};std::function<void(U)> action;U captured{};
 void action_4601a0_record(U at)override{captured=at;action(at);}
 U fired_byte_record(U base,U index)override{return memory->read(base+index*24u+20u,1);}
};
void direct(){constexpr U E=0x1300100,T=0x1301000,A=0x1302000,ALT=0x1303000;Bytes bytes;bytes.add(0x4f2bc8,32);bytes.add(0x1300000,0x4000);bytes.add(0x6e4734,4);bytes.add(0x67dbec,4);bytes.put(0x4f2bc8,4,1);bytes.put(0x4f2bcc,4,E);bytes.put(0x4f2bd0,4,1);bytes.put(0x4f2bd4,4,T);bytes.put(0x4f2bd8,4,2);bytes.put(0x4f2bdc,4,A);
 MissionEventResourceBindings b;b.read=[&](U at,unsigned w){return bytes.get(at,w);};b.write=[&](U at,unsigned w,U v){bytes.put(at,w,v);};MissionEventMemory memory(b);Host host;host.memory=&memory;EventStage stage(&host);stage.attach_source(memory);fails([&]{stage.event(0);});fails([&]{stage.trigger(0);});fails([&]{stage.action(0);});fails([&]{stage.load_tables({}, {}, {});});fails([&]{stage.bind_object_triggers({});});fails([&]{stage.bind_object_actions({});});
 bytes.put(T+4,4,2);bytes.put(T+12,4,2);bytes.put(E+2*24+20,1,0x7e);check(stage.evaluate_trigger_record(T)==0x7e,"Past active count BYTE was changed");bytes.put(T+12,4,0xffffffffu);bytes.put(E-4,1,0x39);check(stage.evaluate_trigger_record(T)==0x39,"Source reference did not wrap");bytes.put(T+12,4,0x100000u);fails([&]{stage.evaluate_trigger_record(T);});EventHost missing;stage.set_host(&missing);fails([&]{stage.evaluate_trigger_record(T);});bytes.put(T+4,4,1);bytes.put(T+8,4,10);fails([&]{stage.evaluate_trigger_record(T);});bytes.put(A+4,4,3);fails([&]{stage.dispatch_action_record(A);});bytes.put(A+4,4,12);fails([&]{stage.dispatch_action_record(A);});stage.set_host(&host);
 bytes.put(E+4,4,T);bytes.put(E+8,4,A);bytes.put(E+20,4,0x00010000);bytes.put(A+4,4,3);host.action=[&](U at){check(at==A&&stage.frame_counter()==16,"Captured action/frame counter");bytes.put(0x4f2bcc,4,ALT);bytes.put(0x4f2bc8,4,0);bytes.put(E+23,1,0x6b);};stage.set_frame_counter(15);stage.frame_driver_step();check(host.captured==A&&stage.frame_counter()==0&&bytes.get(E+20,1)==1&&bytes.get(E+23,1)==0x6b,"Captured event/width writes");check(stage.event_count()==0,"Source count was cached");fails([&]{stage.event_view(0);});
 bytes.put(0x4f2bcc,4,E);bytes.put(0x4f2bc8,4,1);bytes.put(E+20,1,0);stage.set_cursor(0);host.action=[&](U){throw std::runtime_error("Required callee fault");};stage.set_frame_counter(15);fails([&]{stage.frame_driver_step();});check(stage.frame_counter()==16&&bytes.get(E+20,1)==1,"Failure prefix/frame state");
}
void stock(const std::filesystem::path& folder){AssetStore assets(folder);std::ifstream file(folder/"Df.exe",std::ios::binary);AssetBytes exe((std::istreambuf_iterator<char>(file)),{});Fixed3 listener{};U yaw=0;MissionAudioFrameCells cells{0,listener,yaw};const TerrainGeometry* terrain=nullptr;MissionSoundRuntime sound(assets,exe,cells,terrain,{});const auto& raw=sound.asset_bindings();const auto source=assets.read("C05M07.BMS").bytes;const auto mission=decode_mission(source);U objects=0;for(const auto& group:mission.object_groups)objects+=U(group.size());const U offset=268+objects*96+17408+2048+640;check(std::uint64_t(offset)+12+mission.events.size()*24+(mission.triggers.size()+mission.actions.size())*32==source.size(),"Actual BMS event extent");const U name=raw.call(0x497f60,{32,16,0,0});const std::string filename="C05M07.BMS";for(U i=0;i<=filename.size();++i)raw.write(name+i,1,i<filename.size()?U(filename[i]):0);
 MissionEventResourceBindings b;b.read=raw.read;b.write=raw.write;unsigned markers=0;b.call=[&](U site,const std::vector<U>& args)->U{if(site==0x42eea0||site==0x42f020){check(args.empty(),"Marker fixture arguments");++markers;return 0;}return raw.call(site,args);};MissionEventMemory memory(b);Host host;host.memory=&memory;EventStage stage(&host);stage.attach_source(memory);auto load=[&](){check(raw.call(0x499120,{name})!=0xffffffffu,"Actual BMS open");check(raw.call(0x4992d0,{offset,0})==offset,"Actual BMS seek");memory.load_current_file();raw.call(0x499020,{});};load();check(stage.event_count()==mission.events.size(),"Current actual count");auto captured=stage.event_view(0);const U base=captured.source_address(),size=U(mission.events.size()*24);auto trigger=stage.trigger_view(0);trigger.write(4,4,2);trigger.write(12,4,74);const U past=base+74*24+20;const U actual=raw.read(past,1);check(stage.evaluate_trigger_record(trigger.source_address())==actual,"Actual adjacent arena BYTE");
 // Controlled action record uses the loaded allocation. Marker callbacks above are explicit fixtures.
 auto action=stage.action_view(0);action.write(4,4,3);captured.write(0,4,0);captured.write(8,4,action.source_address());captured.write(12,4,0);captured.write(16,4,0);captured.write(20,4,0x10000);host.action=[&](U at){check(at==action.source_address(),"Actual physical action");stage.reset();check(stage.event_count()==0,"Real resource reset count");captured.write(23,1,0xa6);};stage.process_event_record(base);check(captured.read(20,1)==1&&captured.read(23,1)==0xa6,"Current retained allocation after callback reset");const U reused=raw.call(0x497f60,{size,16,0,0});check(reused==base,"Real arena event reuse");raw.write(reused+20,1,0x5c);check(captured.read(20,1)==0x5c,"Captured source sees reused bytes");raw.call(0x4980d0,{reused});load();check(stage.event_view(0).source_address()==base&&captured.read(0,4)==mission.events[0].words[0],"Reload same owner");stage.reset();check(markers==4,"Required marker fixture count");std::cout<<"Actual C05M07 event load/reset/reuse/reload passed; marker providers are fixtures\n";
}
}
int main(int argc,char** argv){try{direct();if(argc==2)stock(argv[1]);else check(argc==1,"Usage: native_events_raw [game-folder]");std::cout<<"Raw event engine checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
